inline std::string Message(const std::string& text){
 if(language==1)return text;
 const auto translated=Tr(text.c_str());if(translated!=text.c_str())return translated;
 const std::pair<std::string_view,std::string_view> prefixes[]={
  {"Downloading ","Laster ned "},
  {"Skin server returned HTTP ","Skin-serveren svarte med HTTP "},
  {"Update server returned HTTP ","Oppdateringsserveren svarte med HTTP "},
  {"Senior Mod+ Detected (\"","Senior mod+ oppdaget (\""},
  {"Automatic updates: published revision ","Automatisk oppdatering: publisert revisjon "},
  {"Automatic updates: cached revision ","Automatisk oppdatering: lagret revisjon "},
  {"Automatic updates: revision ","Automatisk oppdatering: revisjon "},
  {"Bundled offsets: ","Innebygde offsets: "},
  {"Local offsets: ","Lokale offsets: "},
  {"Local file: ","Lokal fil: "},
  {"Selected skin: ","Valgt skin: "},
  {"Queued skin: ","Skin i kø: "},
  {"Skin installation stopped. Original files are preserved in ","Skin-installasjonen stoppet. Originalfilene er bevart i "},

 };
 for(const auto& [from,to]:prefixes)if(text.compare(0,from.size(),from)==0){auto result=std::string(to)+text.substr(from.size());const std::string suffix=" (offline)";if(result.size()>=suffix.size()&&result.compare(result.size()-suffix.size(),suffix.size(),suffix)==0)result.replace(result.size()-suffix.size(),suffix.size()," (uten nett)");return result;}
 return text;
}

